   436  int zmq::zmtp_engine_t::routing_id_msg (msg_t *msg_)
   437  {
   438      const int rc = msg_->init_size (_options.routing_id_size);
   439      errno_assert (rc == 0);
   440      if (_options.routing_id_size > 0)
   441          memcpy (msg_->data (), _options.routing_id, _options.routing_id_size);
