   301  void zmq::session_base_t::read_activated (pipe_t *pipe_)
   302  {
   303      // Skip activating if we're detaching this pipe
   304      if (unlikely (pipe_ != _pipe && pipe_ != _zap_pipe)) {
   305          zmq_assert (_terminating_pipes.count (pipe_) == 1);
   306          return;
   307      }
   308
   309      if (unlikely (_engine == NULL)) {
   310          _pipe->check_read ();
   311          return;
   312      }
   313
   314      if (likely (pipe_ == _pipe))
   315          _engine->restart_output ();
   316      else {
   317          // i.e. pipe_ == zap_pipe
   318          _engine->zap_msg_available ();
   319      }
   320  }
